import {BALANCE as B,CATEGORIES,PHILOSOPHIES,MANUFACTURERS,SPONSORS,TYRES,ROLE_NAMES} from '../../data/config.js';
import {CIRCUITS} from '../../data/circuits.js';
import {FACILITIES,COMPONENTS,ADVANCED_PROJECTS,MEDIA_ACTIONS} from '../../data/part2.js';
import {createCareer,activeContracts,lineup,readiness,bike} from '../state/career.js';
import {ensurePart4} from '../state/part4.js';
import {cash,commitments,forecast,credit,repay} from '../systems/finance.js';
import {quote,negotiate,terminate} from '../systems/contracts.js';
import {standings,settleRace,advance,nextSeason,develop} from '../systems/season.js';
import {p2,facilityLevel,facilityCost,upgradeFacility,orderComponent,startAdvancedProject,staffAction,scoutProspect,signAcademy,promoteProspect,runMediaAction,valuation,createInvestorOffer,decideInvestor,resolveWorldEvent} from '../systems/part2.js';
import {enterWeekend,startSession,currentCircuit,tick,command,setSetup,finishTimedSession,ranking} from '../simulation/engine.js';
import {save,load,slots,encode,decode} from '../services/save.js';
import {alertTone} from '../services/audio.js';
import {trackSVG,updateTrack} from '../race/track.js';
import {TEXT as T,money,time,esc} from './text.js';
import {operations,academy,mediaCenter,worldCenter} from './part2-pages.js';
import {installPart2Controller} from './part2-controller.js';
let state=null,view='dashboard',speed=1,paused=true,manifest={},selectedKind='rider',filter='all',accumulator=0,lastFrame=0,lastDraw=0,lastSave=0;
const app=document.getElementById('app'),dialog=document.getElementById('dialog');
const asset=key=>manifest[key]?.src?new URL(manifest[key].src,document.baseURI).href:'';
const image=(key,cls='',alt='')=>asset(key)?`<img class="${cls}" src="${esc(asset(key))}" alt="${esc(alt)}" loading="lazy">`:'';
const btn=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const badge=text=>`<span class="badge">${esc(text)}</span>`;
const rider=id=>state.riders.find(r=>r.id===id);
const team=id=>id==='player'?state.team:state.teams.find(t=>t.id===id);
const label=(text,input)=>`<label>${text}${input}</label>`;
const option=(value,text,selected=false)=>`<option value="${esc(value)}" ${selected?'selected':''}>${esc(text)}</option>`;
const flag=country=>`<img class="flag" src="assets/flags/${country.toLowerCase()}.svg" alt="${country}">`;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000);alertTone(state?.settings.sound);}
function persist(){try{save(state);lastSave=performance.now();}catch(e){toast('Não foi possível salvar neste navegador. Exporte um backup: '+e.message);}}
function modal(html){dialog.innerHTML=`${btn('×','close','','close')}<div class="modal-body">${html}</div>`;if(!dialog.open)dialog.showModal();}
function confirmAction(title,body,action,extra=''){modal(`<h2>${title}</h2><p>${body}</p><div class="actions">${btn('Cancelar','close')}${btn('Confirmar',action,extra,'primary')}</div>`);}
function tutorialContent(){const done=state?.part4?.tutorial?.completed||[];const steps=[['fundacao','01','Fundar a equipe','Defina categoria, filosofia, cor e caixa inicial. A carreira é salva automaticamente no navegador.','dashboard'],['contratos','02','Montar o paddock','Contrate dois pilotos, engenharia e mecânica. Escolha fabricante e patrocínio para liberar uma etapa.','people'],['fim-de-semana','03','Treino e classificação','No treino, solte as motos, leia a recomendação e ajuste a moto. Na classificação, a melhor volta fecha o grid.','calendar'],['pitwall','04','Comandar a corrida','A transmissão mostra posições, gaps, bandeiras e clima. Em cada cartão, controle motor, ritmo, uso do pneu e o plano do pit.','session'],['resultado','05','Ler o resultado','A bandeirada apresenta posição, avatar, bandeira, tempo, pontos, incidentes e impacto financeiro.','championship'],['inbox','06','Gerir a equipe','A caixa de entrada registra contratos, mídia, investidores, academia, P&D e resultados. Use-a para priorizar suas decisões.','inbox']];return `<span class="eyebrow">TUTORIAL COMPLETO · PARTE 4</span><h2>Comande do paddock à bandeirada</h2><p>Este é um simulador de gestão: o desempenho é calculado por piloto, moto, acerto, pneus, combustível, clima, desgaste, risco e decisões tomadas em pista.</p><div class="tutorial-list">${steps.map(([id,n,title,body,target])=>`<article class="tutorial-step ${done.includes(id)?'done':''}"><span>${n}</span><div><h3>${esc(title)}</h3><p>${esc(body)}</p></div>${done.includes(id)?'<b>✓</b>':btn('Ver área','tutorial-go',`data-step="${id}" data-view="${target}"`,'compact')}</article>`).join('')}</div><div class="actions">${btn('Marcar tutorial como concluído','tutorial-complete','','primary')}${btn('Fechar','close')}</div>`;}
installPart2Controller({getState:()=>state,render,persist,toast,confirmAction,closeDialog:()=>dialog.close()});
function portrait(person){if(person.portraitSheet){const cols=person.portraitCols||3,rows=person.portraitRows||4,index=person.portraitIndex||0,x=cols>1?(index%cols)/(cols-1)*100:0,y=rows>1?Math.floor(index/cols)/(rows-1)*100:0;return `<div class="portrait portrait-sprite" role="img" aria-label="${esc(person.name)}" style="--portrait:url('${esc(asset(person.portraitSheet))}');--portrait-size-x:${cols*100}%;--portrait-size-y:${rows*100}%;--portrait-x:${x}%;--portrait-y:${y}%"></div>`;}return image(person.portrait,'portrait',person.name)||`<div class="monogram" aria-label="${esc(person.name)}">${esc(person.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div>`;}
function brandLogo(m){return `<div class="brand-lockup" style="--brand-accent:${m.id==='ktm'?'#ff5b00':m.id==='kairo'||m.id==='aprilia'?'#e32033':m.id==='veloce'||m.id==='bmw'?'#2f9ddd':'#ed2336'}"><img src="assets/brands/${esc(m.logo)}.svg" alt="${esc(m.name)}"><div><span>${flag(m.origin)}</span><strong>${esc(m.character)}</strong><small>${esc(m.engine)}</small></div></div>`;}
function title(kicker,title,description=''){return `<header class="page-title"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div></header>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,note])=>`<div class="stat"><span>${label}</span><strong>${value}</strong><small>${note||''}</small></div>`).join('')}</div>`;}
function welcome(){const available=slots();app.innerHTML=`<div class="welcome premium-welcome" style="--scene:url('${asset('art-002')||asset('garage')}')"><div class="welcome-art"><div class="brand large brand-graphic official-logo"><img src="assets/brands/mrm-official-logo.png" alt="Moto Racing Manager"></div><div class="welcome-copy"><span class="eyebrow">CARREIRA · PARTE 4</span><h1>Construa.<br>Comande.<br>Vença.</h1><p>Um paddock vivo, decisões técnicas profundas e a pressão real de uma temporada mundial.</p><div class="feature-chips"><span>44 PERSONAGENS COM ROSTO</span><span>6 FABRICANTES REAIS</span><span>SIMULAÇÃO TÉCNICA</span></div></div><div class="welcome-foot">10 CIRCUITOS &nbsp; / &nbsp; P&D AVANÇADO &nbsp; / &nbsp; MUNDO DINÂMICO</div></div><section class="welcome-panel"><span class="eyebrow">CENTRAL DA EQUIPE</span><h2>Fundar uma equipe</h2><p>Defina a identidade, escolha a categoria e assuma o pit wall.</p><form id="new-career"><div class="form-grid">${label('Nome da equipe','<input name="name" maxlength="40" required value="Valença Racing">')}${label('Sigla','<input name="short" maxlength="8" required value="VLR">')}${label('País',`<select name="country">${['BR','PT','IT','JP','US','AU','ES','FR'].map(x=>option(x,x)).join('')}</select>`)}${label('Cidade-base','<input name="city" maxlength="40" required value="São Paulo">')}${label('Categoria',`<select name="category">${CATEGORIES.map(c=>option(c.id,c.name+' · '+money(B.initialCash*c.cost),c.id==='inter')).join('')}</select>`)}${label('Filosofia',`<select name="philosophy">${PHILOSOPHIES.map(p=>option(p.id,p.name,p.id==='technical')).join('')}</select>`)}${label('Cor principal','<input name="color" type="color" value="#ff493e">')}${label('Código da carreira (seed)','<input name="seed" placeholder="Opcional" maxlength="40">')}</div><p class="hint">O capital varia com a categoria. Contratos e decisões consomem esse orçamento.</p><button class="primary wide mega-button" type="submit">CRIAR EQUIPE E ENTRAR NO PADDOCK <span>→</span></button></form><div class="divider"></div><h3>Continuar carreira</h3><div class="save-list">${available.filter(s=>s.name).map(s=>btn(`${esc(s.name)} · Ano ${s.season} / Etapa ${Math.min(s.round+1,10)}`,'load',`data-slot="${s.id}"`,'save-button')).join('')||'<p class="muted">Nenhuma carreira salva neste navegador.</p>'}</div>${btn('Importar backup','import','','text-button')}<input id="import-file" type="file" accept="application/json,.json" hidden></section></div>`;}
function render(){if(!state){welcome();return;}ensurePart4(state);const settings=state.settings;document.documentElement.style.setProperty('--accent',state.team.color);document.documentElement.style.setProperty('--font-scale',settings.scale||1);document.body.classList.toggle('high-contrast',!!settings.contrast);document.body.classList.toggle('reduced-motion',!!settings.reducedMotion);document.body.classList.toggle('performance',settings.graphics==='performance');const activeSession=view==='session';app.innerHTML=`<div class="shell ${activeSession?'in-session':''}"><aside class="sidebar"><a href="#" class="brand brand-graphic official-logo sidebar-logo" data-action="nav" data-view="dashboard"><img src="assets/brands/mrm-official-logo.png" alt="Moto Racing Manager"></a><div class="team-lockup"><span class="team-mark">${esc(state.team.short)}</span><div><strong>${esc(state.team.name)}</strong><small>${esc(CATEGORIES.find(c=>c.id===state.category).name)}</small></div></div><nav>${T.nav.map(([id,name,n])=>btn(`<span>${n}</span><b>${name}</b>`,'nav',`data-view="${id}" aria-current="${view===id?'page':'false'}"`,view===id?'active':'')).join('')}</nav><div class="sidebar-bottom">TEMPORADA ${String(state.season).padStart(2,'0')}<br><span>Parte 4 · Corrida ao vivo</span></div></aside><div class="workspace"><header class="topbar"><div><span class="live-dot"></span> ${esc(T.phase[state.phase])}<span class="top-secondary"> / ${state.round<10?'ETAPA '+String(state.round+1).padStart(2,'0')+' DE 10':'FIM DA TEMPORADA'}</span></div><div class="top-actions"><strong>${money(cash(state))}</strong>${btn('SALVAR CARREIRA','save','','compact')}${btn('⛶','fullscreen','aria-label="Alternar tela cheia"','compact')}${btn('GUIA','tutorial','aria-label="Abrir tutorial"','compact')}</div></header><main id="main">${page()}</main><footer class="footer"><span>${esc(state.team.city)} · ${esc(state.team.country)}</span><span>PARTE 4 · TRANSMISSÃO AO VIVO, SALVAMENTO E BACKUPS</span></footer></div></div><input id="import-file" type="file" accept="application/json,.json" hidden>`;document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{img.style.display='none';},{once:true}));if(activeSession)drawSession();}
function page(){switch(view){case'people':return people();case'partners':return partners();case'finance':return finances();case'garage':return garage();case'operations':return operations(state,asset);case'academy':return academy(state,asset);case'media':return mediaCenter(state,asset);case'world':return worldCenter(state,asset);case'calendar':return calendar();case'championship':return championship();case'inbox':return inbox();case'settings':return settingsPage();case'session':return sessionPage();case'grid':return gridPage();case'result':return resultPage();default:return dashboard();}}
function guide(){if(!state.settings.guide)return '';return `<aside class="guide">${image('guide','guide-avatar','Sofia, assessora')}<div><strong>Sofia · Assessora executiva</strong><p>${T.guide[state.phase]}</p></div>${btn('Entendi','hide-guide','','compact')}</aside>`;}
function dashboard(){const s=state,c=currentCircuit(s),missing=readiness(s),pos=standings(s,true).findIndex(t=>t.id==='player')+1;return `${title('CENTRAL DA EQUIPE',esc(s.team.name),'Seu próximo passo começa aqui.')}${stats([['Caixa disponível',money(cash(s)),forecast(s)<0?'Projeção exige atenção':'Reserva operacional'],['Campeonato','P'+pos,(s.teamStandings.player||0)+' pontos'],['Reputação',s.team.reputation+'/100','Interesse comercial'],['Moral',s.team.morale+'%','Ambiente da equipe']])}<section class="hero" style="--scene:url('${asset(c?.art||'podium')}')"><div class="hero-copy"><span class="eyebrow">${c?'PRÓXIMO DESAFIO':'BANDEIRA QUADRICULADA'}</span><h2>${c?flag(c.country)+' '+c.name:'Temporada '+s.season+' concluída'}</h2><p>${c?`${c.city} · ${c.length.toFixed(1)} km · ${c.continent}`:'O campeonato terminou. Sua história fica no arquivo da carreira.'}</p><div class="hero-meta">${badge(T.phase[s.phase])}${c?badge(c.temp+' °C · Risco de chuva '+Math.round(c.rain*100)+'%'):''}</div>${btn(s.phase==='seasonEnd'?'Ver balanço da temporada':s.phase==='management'?(missing.length?'Preparar minha equipe':'Viajar para a etapa'):'Continuar fim de semana','continue','','primary')}</div><div class="hero-track">${c?trackSVG(c):''}</div></section>${guide()}<div class="columns"><section class="panel"><div class="panel-heading"><h2>Plano de trabalho</h2><span>${missing.length?'AÇÃO NECESSÁRIA':'PRONTO PARA CORRER'}</span></div>${missing.length?missing.map(x=>`<div class="check-row"><span class="check pending">!</span><span>${x}</span>${btn('Abrir','nav',`data-view="${x.includes('patrocínio')||x.includes('fabricante')?'partners':'people'}"`,'compact')}</div>`).join(''):`<div class="check-row"><span class="check">✓</span><p>Núcleo operacional completo. Confira os parceiros e prepare o acerto.</p></div>`}<div class="panel-heading"><h3>Compromissos contratados</h3><b>${money(commitments(s))}</b></div><p class="muted">Valor futuro dos contratos ativos. A projeção também considera receitas comerciais e operação.</p></section><section class="panel"><div class="panel-heading"><h2>Últimas do paddock</h2>${btn('Ver todas','nav','data-view="inbox"','text-button')}</div>${s.news.slice(0,3).map(n=>`<article class="news-row"><span class="eyebrow">ANO ${n.season} · ETAPA ${n.round+1}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></article>`).join('')}</section></div>`;}
function people(){const s=state,entities=selectedKind==='rider'?s.riders:s.staff;return `${title('DEPARTAMENTO HUMANO','Pessoas que fazem a diferença','Negocie salário por etapa e duração do contrato.') }<div class="tabs">${btn('Pilotos','people-tab','data-kind="rider"',selectedKind==='rider'?'selected':'')}${btn('Staff','people-tab','data-kind="staff"',selectedKind==='staff'?'selected':'')}<span class="muted">${lineup(s).length}/2 pilotos contratados</span></div><div class="people-grid">${entities.map(p=>{const c=s.contracts.find(c=>c.kind===selectedKind&&c.entityId===p.id&&c.status==='ACTIVE');return `<article class="person-card ${c?.teamId==='player'?'owned':''}"><div class="person-visual">${portrait(p)}<span class="person-number">${p.number?'#'+p.number:ROLE_NAMES[p.role]}</span></div><div class="person-body"><span class="eyebrow">${p.nationality?esc(p.nationality)+' · '+p.age+' ANOS':ROLE_NAMES[p.role]}</span><h2>${esc(p.name)}</h2><p>${esc(p.style||p.personality)}</p><div class="mini-stats">${(selectedKind==='rider'?[['Ritmo',p.attributes.speed],['Chuva',p.attributes.wet],['Pneus',p.attributes.tyre]]:[['Precisão',p.attributes.precision],['Pressão',p.attributes.pressure],['Inovação',p.attributes.innovation]]).map(([l,v])=>`<div><span>${l}</span><b>${v}</b></div>`).join('')}</div><div class="contract-line"><b>${money(quote(s,selectedKind,p.id))}</b><small>/ etapa</small></div>${c?badge(c.teamId==='player'?'Sua equipe · até ano '+c.endSeason:team(c.teamId)?.name||'Contratado'):btn('Negociar contrato','offer',`data-kind="${selectedKind}" data-id="${p.id}"`,'primary wide')}${btn('Ver perfil','profile',`data-kind="${selectedKind}" data-id="${p.id}"`,'text-button')}</div></article>`;}).join('')}</div>`;}
function partners(){return `${title('REDE DE PARCEIROS','Fabricantes e tecnologia de fábrica','Compare a identidade técnica de cada pacote; a escolha muda o comportamento da moto.')}<div class="section-photo partner-hero" style="--scene:url('${asset('garage')||asset('contracts')}')"><div><span class="eyebrow">FÁBRICA + EQUIPE</span><h2>Escolha a alma<br>da sua moto.</h2><p>Seis fabricantes reais, seis filosofias de engenharia.</p></div></div><h2 class="section-label">Fabricantes de motor e chassi</h2><div class="manufacturer-grid">${MANUFACTURERS.map(m=>`<article class="panel manufacturer-card ${state.team.manufacturer===m.id?'selected-manufacturer':''}">${brandLogo(m)}<p>${m.description}</p>${bars(m.bike)}<div class="supplier-price"><div><span>PACOTE POR ETAPA</span><h3>${money(quote(state,'supplier',m.id))}</h3></div>${state.team.manufacturer===m.id?badge('PARCEIRO OFICIAL'):btn('NEGOCIAR PACOTE','offer',`data-kind="supplier" data-id="${m.id}"`,'primary wide')}</div></article>`).join('')}</div><p class="trademark-note">Marcas e nomes pertencem aos respectivos titulares. Projeto independente, sem afiliação oficial.</p><h2 class="section-label">Patrocinadores</h2><div class="cards three">${SPONSORS.map(p=>`<article class="panel sponsor sponsor-premium"><span class="eyebrow">${p.sector}</span><div class="sponsor-wordmark">${p.name}</div><p>${p.description}</p><h3>${money(quote(state,'sponsor',p.id))}<small> / etapa</small></h3><p class="muted">Bônus base: ${money(p.bonus)} por piloto dentro da meta.</p>${activeContracts(state,'sponsor').some(c=>c.entityId===p.id)?badge('Patrocínio ativo'):btn('NEGOCIAR PATROCÍNIO','offer',`data-kind="sponsor" data-id="${p.id}"`,'primary wide')}</article>`).join('')}</div>`;}
function bars(values){return `<div class="bars">${Object.entries(values).map(([k,v])=>`<div><span>${esc(T.attributes[k]||k)}</span><b>${Math.round(v)}</b><progress value="${v}" max="100">${v}</progress></div>`).join('')}</div>`;}
function garage(){const s=state;return `${title('CENTRO TÉCNICO','Garagem e engenharia','A moto responde à pista, aos pneus e à sua equipe.') }<div class="garage-layout"><div class="garage-photo" style="--scene:url('${asset('garage')}')"><span class="eyebrow">${esc(MANUFACTURERS.find(m=>m.id===s.team.manufacturer)?.name||'SELECIONE UM FABRICANTE')}</span>${s.team.manufacturer?`<img class="supplier-watermark" src="assets/brands/${MANUFACTURERS.find(m=>m.id===s.team.manufacturer)?.logo}.svg" alt="${esc(MANUFACTURERS.find(m=>m.id===s.team.manufacturer)?.name)}">`:''}<h2>${esc(s.team.short)} / ${String(s.season).padStart(2,'0')}</h2></div><section class="panel"><h2>Pacote técnico</h2>${bars(bike(s,'player'))}<p class="muted">As pistas valorizam atributos diferentes. Confiabilidade influencia falhas; velocidade não resume a moto.</p></section></div>${s.weekend&&['practice','qualifying'].includes(s.phase)?setupForm():''}<h2 class="section-label">Projetos de desenvolvimento</h2><p class="muted">Um projeto por vez · validação em duas etapas · risco de reprovação de ${Math.round(B.projectRisk*100)}%</p><div class="cards three">${['speed','braking','reliability'].map(k=>`<section class="panel"><h3>${T.attributes[k]}</h3><p>Desenvolver um pacote e validar nas próximas etapas.</p>${btn('Iniciar projeto','develop',`data-id="${k}"`,'wide')}</section>`).join('')}</div>${s.projects.map(p=>`<div class="project-row"><b>${T.attributes[p.attribute]}</b>${badge(p.status==='ACTIVE'?p.remaining+' etapa(s) restantes':p.status==='COMPLETE'?'Validado · +'+p.gain:'Reprovado')}<span>${money(p.cost)}</span></div>`).join('')}`;}
function setupForm(){const w=state.weekend;return `<section class="panel setup-panel"><h2>Acerto da moto</h2><form id="setup-form"><div class="form-grid">${T.setup.map((t,i)=>label(t,`<input type="range" min="0" max="100" name="s${i}" value="${w.setup[i]}"><output>${w.setup[i]}</output>`)).join('')}</div><div class="actions"><button type="submit" class="primary">Aplicar acerto</button>${w.feedback?btn('Usar recomendação do engenheiro','recommend'):''}</div></form>${w.feedback?'<p class="hint">A recomendação usa o treino e a competência do engenheiro. Ela aproxima a janela de acerto, sem garantir o melhor resultado.</p>':''}</section>`;}
function calendar(){return `${title('WORLD TOUR','Calendário internacional','Dez pistas originais. Dez desafios técnicos.') }<div class="circuit-grid">${CIRCUITS.map((c,i)=>`<article class="circuit-card">${image(c.art,'circuit-photo',c.name)}<div class="circuit-overlay"><span class="round-number">${String(i+1).padStart(2,'0')}</span>${flag(c.country)}<h2>${c.name}</h2><p>${c.city} · ${c.length.toFixed(1)} km</p>${badge(i<state.round?'Concluída':i===state.round?'Próxima etapa':c.continent)}${btn('Ficha do circuito','circuit',`data-id="${c.id}"`,'compact')}</div></article>`).join('')}</div>`;}
function championship(){return `${title('CLASSIFICAÇÃO OFICIAL','Campeonato','Empates decididos por contagem de melhores posições.') }<div class="columns"><section class="panel"><h2>Pilotos</h2>${table(['Pos.','Piloto','Equipe','Pontos'],standings(state).filter(x=>x.points||state.contracts.some(c=>c.entityId===x.id&&c.status==='ACTIVE')).map((x,i)=>[i+1,esc(rider(x.id).name),esc(team(state.contracts.find(c=>c.entityId===x.id&&c.status==='ACTIVE')?.teamId)?.name||'Livre'),`<b>${x.points}</b>`]))}</section><section class="panel"><h2>Equipes</h2>${table(['Pos.','Equipe','Pontos'],standings(state,true).map((x,i)=>[i+1,esc(team(x.id).name),`<b>${x.points}</b>`]))}<h2 class="section-label">Arquivo de temporadas</h2>${state.history.length?state.history.map(h=>`<article class="news-row"><h3>Temporada ${h.season}</h3><p>Campeão: ${esc(rider(h.champion).name)}<br>Equipe: ${esc(team(h.teamChampion).name)}<br>Sua equipe: ${h.points} pontos</p></article>`).join(''):'<p class="muted">A primeira temporada ainda está em disputa.</p>'}</section></div>`;}
function table(head,rows){return `<div class="table-scroll"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function finances(){const s=state;return `${title('DIRETORIA FINANCEIRA','Cada decisão tem um custo','Valores em euros. Salários, patrocínios e fornecimento são cobrados por etapa.')}${stats([['Caixa',money(cash(s)),'Saldo reconciliado do ledger'],['Compromissos',money(commitments(s)),'Contratos até o vencimento'],['Projeção do ano',money(forecast(s)),'Sem premiações futuras'],['Dívida',money(s.debt),'Juros de 2,5% por etapa']])}<div class="actions">${btn(s.debt?'Quitar crédito':'Solicitar crédito de '+money(B.creditLimit),'credit-request')}</div><section class="panel"><h2>Contratos ativos</h2>${table(['Parceiro','Tipo','Por etapa','Até temporada',''],activeContractsAll().map(c=>[esc(entityName(c.kind,c.entityId)),esc(c.kind),money(c.value),c.endSeason,btn('Rescindir','terminate-request',`data-id="${c.id}"`,'compact')]))}</section><section class="panel section-label"><h2>Movimentações do caixa</h2>${table(['Ano / Etapa','Descrição','Movimentação'],s.ledger.filter(x=>x.teamId==='player').slice().reverse().map(x=>[`${x.season} / ${x.round+1}`,esc(x.description),`<span class="${x.amount>=0?'positive':'negative'}">${money(x.amount)}</span>`]))}</section>`;}
function activeContractsAll(){return state.contracts.filter(c=>c.teamId==='player'&&c.status==='ACTIVE');}
function entityName(kind,id){return (kind==='rider'?state.riders:kind==='staff'?state.staff:kind==='sponsor'?SPONSORS:MANUFACTURERS).find(e=>e.id===id)?.name||id;}
function inbox(){const read=state.part4.mailbox.read;const messages=state.news;const unread=messages.filter(n=>!read.includes(n.id)).length;return `${title('CENTRAL DE MENSAGENS','Caixa de entrada',`${unread} mensagem(ns) aguardando leitura · tudo que acontece no paddock chega aqui.`)}<section class="mail-command"><div><span class="eyebrow">PAINEL DE EQUIPE</span><h2>Decida com contexto</h2><p>Contratos, desempenho, mídia, P&D, investidores, academia e ocorrências de corrida deixam um registro rastreável.</p></div><div>${btn('ABRIR TUTORIAL','tutorial','','primary')}</div></section><div class="inbox-list mailbox">${messages.map(n=>`<article class="panel mail-item ${read.includes(n.id)?'read':'unread'}"><div class="mail-icon">${n.title.includes('Bandeirada')?'🏁':n.title.includes('Projeto')?'⚙':'✉'}</div><div><span class="eyebrow">T${n.season} · ETAPA ${Math.min(n.round+1,10)} · ${read.includes(n.id)?'LIDA':'NOVA'}</span><h2>${esc(n.title)}</h2><p>${esc(n.body)}</p></div>${read.includes(n.id)?'<span class="mail-read">LIDA</span>':btn('Ler','mail-read',`data-id="${n.id}"`,'compact')}</article>`).join('')||'<section class="panel"><p>Nenhuma mensagem até o momento.</p></section>'}</div>`;}
function settingsPage(){const s=state;return `${title('SUA CARREIRA','Salvamento e preferências','O progresso pertence a este navegador. Exporte um backup antes de trocar de aparelho.') }<div class="columns"><section class="panel"><h2>Slots de carreira</h2>${slots().map(slot=>`<div class="slot"><div><strong>${slot.id==='auto'?'Automático':'Slot '+slot.id}</strong><p>${slot.name?esc(slot.name)+' · Ano '+slot.season:'Vazio'}</p></div>${slot.id!=='auto'?btn('Salvar','manual-save-request',`data-slot="${slot.id}"`,'compact'):''}${slot.name?btn('Carregar','load-request',`data-slot="${slot.id}"`,'compact'):''}</div>`).join('')}<div class="actions">${btn('Exportar backup JSON','export','','primary')}${btn('Importar backup','import')}</div></section><section class="panel"><h2>Experiência</h2><form id="settings-form">${label('Qualidade gráfica',`<select name="graphics">${['balanced','quality','performance'].map((x,i)=>option(x,['Equilibrado','Qualidade','Desempenho'][i],s.settings.graphics===x)).join('')}</select>`)}${label('Escala do texto',`<select name="scale">${[1,1.15,1.3].map(x=>option(x,Math.round(x*100)+'%',s.settings.scale===x)).join('')}</select>`)}${[['guide','Orientações da Sofia'],['contrast','Alto contraste'],['reducedMotion','Reduzir movimento'],['sound','Som de confirmação']].map(([key,text])=>`<label class="checkbox"><input type="checkbox" name="${key}" ${s.settings[key]?'checked':''}>${text}</label>`).join('')}<button type="submit" class="primary">Aplicar preferências</button></form><div class="divider"></div>${btn('Voltar ao menu inicial','menu-request')}</section></div>`;}
function sessionPage(){if(!state.session)return preSession();const q=state.session;return `${title('TRANSMISSÃO AO VIVO · '+esc(currentCircuit(state).name),T.phase[state.phase])}<section class="broadcast-rail"><span class="on-air">● AO VIVO</span><b>MRM RACE CONTROL</b><span id="broadcast-headline">Preparando cobertura da corrida</span><span class="broadcast-round">${flag(currentCircuit(state).country)} ETAPA ${String(state.round+1).padStart(2,'0')}</span></section><div class="session-toolbar tv-toolbar"><div id="session-clock" class="session-clock"></div><span id="weather" class="badge"></span><span id="weather-trend" class="weather-trend"></span><div class="actions">${btn(paused?'▶ RETOMAR':'Ⅱ PAUSAR','pause','id="pause-btn"','primary compact')}${[1,2,4,8,32].map(x=>btn(x+'×','speed',`data-speed="${x}"`,speed===x?'selected compact':'compact')).join('')}${btn('RESULTADO','finish-session','id="finish-btn" disabled','compact')}</div></div><div class="tv-race-layout"><section class="tv-stage"><div class="camera-banner"><span>CAM 01 · VISÃO AÉREA</span><b id="flag-state">PISTA ABERTA</b><span id="lap-progress"></span></div>${trackSVG(currentCircuit(state),q.entries,state.team.color)}<div class="tv-lower-third"><div><span>VOLTA MAIS RÁPIDA</span><b id="fastest-lap">—</b></div><div><span>EVENTO DE PISTA</span><b id="track-event">Largada sob controle</b></div><div><span>ESTRATÉGIA</span><b id="strategy-pulse">Monitorando pneus</b></div></div></section><section class="timing-panel broadcast-timing"><div class="panel-heading"><div><span class="eyebrow">CRONOMETRAGEM OFICIAL</span><h2>Live ranking</h2></div><select id="timing-filter" aria-label="Filtrar pilotos">${option('all','Grid completo',filter==='all')}${option('player','Minha equipe',filter==='player')}</select></div><div id="timing"></div></section></div><section class="player-garage"><div class="garage-header"><span class="eyebrow">PIT WALL · DECISÃO IMEDIATA</span><p>As escolhas abaixo entram na telemetria e afetam ritmo, desgaste, consumo, risco e duração da parada.</p></div><div class="driver-controls">${q.entries.filter(e=>e.teamId==='player').map(e=>{const r=rider(e.riderId);return `<section class="panel driver-control broadcast-driver"><header><div class="driver-chip">${portrait(r)}<div><span>${flag(r.nationality)}</span><b>#${e.number} ${esc(r.name)}</b><small>${esc(team(e.teamId).name)}</small></div></div><span id="status-${e.riderId}" class="status-pill"></span></header><div id="telemetry-${e.riderId}" class="telemetry live-telemetry"></div><div class="command-row">${btn('CHAMAR AO BOX','box',`data-id="${e.riderId}"`,'primary')}${btn('PIT: '+TYRES[e.pitTyre||e.tyre].letter,'pit-plan-label',`data-id="${e.riderId}"`,'compact')}</div><div class="tech-controls live-controls"><label>Motor<select data-engine="${e.riderId}">${['save','balanced','attack'].map((v,i)=>option(v,['Economia','Normal','Potência'][i],v===e.engineMode)).join('')}</select></label><label>Ritmo<select data-pace="${e.riderId}">${[-1,0,1].map((p,i)=>option(p,['Eco','Equilibrado','Ataque'][i],p===e.pace)).join('')}</select></label><label>Uso de pneu<select data-tyre-mode="${e.riderId}">${['conserve','balanced','push'].map((v,i)=>option(v,['Poupar','Normal','Forte'][i],v===(e.tyreMode||'balanced'))).join('')}</select></label><label>Pneu no pit<select data-pit-plan="${e.riderId}">${Object.entries(TYRES).map(([id,t])=>option(id,t.name,id===(e.pitTyre||e.tyre))).join('')}</select></label><label>Parada<select data-pit-mode="${e.riderId}">${['safe','normal','fast'].map((v,i)=>option(v,['Segura','Normal','Rápida'][i],v===(e.pitMode||'normal'))).join('')}</select></label><label>Eletrônica<select data-electronics="${e.riderId}">${['safe','balanced','aggressive'].map((v,i)=>option(v,['Segura','Equilibrada','Direta'][i],v===e.electronics)).join('')}</select></label><label class="brake-control">Freio dianteiro<input data-brake="${e.riderId}" type="range" min="48" max="56" step=".5" value="${e.brakeBias}"><output>${e.brakeBias}%</output></label></div></section>`;}).join('')}</div></section><section class="panel radio broadcast-radio"><div class="panel-heading"><h2>Rádio da equipe</h2><span>CANAL ABERTO</span></div><div id="radio-feed"></div></section>`;}
function preSession(){return `${title('FIM DE SEMANA',T.phase[state.phase],esc(currentCircuit(state)?.name||''))}<div class="section-photo" style="--scene:url('${asset('garage')}')"><h2>Engenharia preparada.<br>Hora de ir para a pista.</h2></div>${guide()}${setupForm()}<section class="panel"><h2>Plano de saída</h2><p>Treino de 8 minutos; classificação de 7 minutos. As motos permanecem nos boxes até sua liberação. Cada saída coleta até três voltas cronometradas.</p><div class="actions">${label('Composto',`<select id="pre-tyre">${Object.entries(TYRES).map(([id,t])=>option(id,t.name,id===state.weekend.tyre)).join('')}</select>`)}${btn('Abrir '+T.phase[state.phase],'start-session','','primary')}</div></section>${runAnalysis()}`;}
function runAnalysis(){const runs=state.weekend?.runs||[];if(!runs.length)return '';return `<section class="panel section-label"><h2>Análise dos runs</h2>${table(['Piloto','Volta','Tempo','Pneu','Desgaste'],runs.map(r=>[esc(rider(r.riderId).short),r.lap,time(r.time),TYRES[r.tyre].name,Math.round(r.wear)+'%']))}</section>`;}
function gridPage(){const w=state.weekend;return `${title('PRÉ-LARGADA','Grid de largada',flag(currentCircuit(state).country)+' '+esc(currentCircuit(state).name))}<section class="grid-broadcast" style="--scene:url('${asset(currentCircuit(state).art)}')"><div class="broadcast-rail"><span class="on-air">● AO VIVO</span><b>FORMING GRID</b><span>As luzes apagam em instantes</span><span class="broadcast-round">${flag(currentCircuit(state).country)} ETAPA ${String(state.round+1).padStart(2,'0')}</span></div><div class="start-lights" aria-label="cinco luzes de largada">● ● ● ● ●</div><div class="grid-slots tv-grid">${w.grid.map(g=>{const r=rider(g.riderId);return `<article class="grid-slot ${g.teamId==='player'?'player':''}"><span class="grid-position">P${g.gridPosition}</span><div class="grid-avatar">${portrait(r)}</div><div class="grid-rider"><b>${flag(r.nationality)} #${r.number} ${esc(r.short)}</b><small>${esc(team(g.teamId).name)}</small><strong>${time(g.best)}</strong></div></article>`;}).join('')}</div></section>${guide()}<section class="panel strategy-deck"><div class="panel-heading"><div><span class="eyebrow">ESTRATÉGIA DE LARGADA</span><h2>Decisões que chegam ao rádio</h2></div><span class="badge">Dados ao vivo</span></div><div class="grid-strategy"><div class="strategy-inputs">${label('Pneu de largada',`<select id="grid-tyre">${Object.entries(TYRES).map(([id,t])=>option(id,t.name,id===w.tyre)).join('')}</select>`)}${label('Ritmo inicial',`<select id="grid-pace">${[-1,0,1].map((p,i)=>option(p,['Poupar','Equilibrado','Ataque'][i],p===w.pace)).join('')}</select>`)}${label('Mapa do motor',`<select id="grid-engine">${['save','balanced','attack'].map((v,i)=>option(v,['Economia','Normal','Potência'][i],v===(w.engineMode||'balanced'))).join('')}</select>`)}${label('Eletrônica',`<select id="grid-electronics">${['safe','balanced','aggressive'].map((v,i)=>option(v,['Segura','Equilibrada','Direta'][i],v===(w.electronics||'balanced'))).join('')}</select>`)}${label('Freio dianteiro',`<input id="grid-brake" type="range" min="48" max="56" step=".5" value="${w.brakeBias||52}"><output>${w.brakeBias||52}%</output>`)}</div>${btn('ALINHAR E LARGAR','race-start','','primary mega-button')}</div><div class="strategy-notes"><span><b>ECO</b> poupa combustível e reduz estresse do motor</span><span><b>PNEU FORTE</b> dá aderência imediata, mas aumenta desgaste</span><span><b>CLIMA</b> muda em tempo real; deixe um composto pronto</span></div></section>`;}
function resultPage(){if(state.phase==='seasonEnd')return `${title('TEMPORADA '+state.season,'A história está escrita.')}<div class="section-photo" style="--scene:url('${asset('podium')}')"><h2>${esc(rider(standings(state)[0].id).name)}<br>Campeão da temporada</h2></div>${stats([['Sua equipe',(state.teamStandings.player||0)+' pontos','Classificação final'],['Caixa final',money(cash(state)),'Após todas as etapas']])}<div class="actions">${btn('Começar próxima temporada','next-season','','primary')}${btn('Ver campeonato','nav','data-view="championship"')}${btn('Exportar carreira','export')}</div>`;const r=state.results.at(-1);if(!r)return '<p>Nenhum resultado disponível.</p>';const winner=r.entries[0],winnerRider=rider(winner.riderId);return `${title('BANDEIRA QUADRICULADA','Resultado da corrida',esc(CIRCUITS.find(c=>c.id===r.circuit).name))}<section class="result-broadcast" style="--scene:url('${asset('podium')}')"><span class="on-air">RESULTADO OFICIAL</span><div class="winner-profile">${portrait(winnerRider)}<div><span class="eyebrow">VENCEDOR</span><h2>${flag(winnerRider.nationality)} ${esc(winnerRider.name)}</h2><p>${esc(team(winner.teamId).name)} · ${time(winner.time)}</p></div></div><div class="result-weather">${r.weather.wet>.35?'🌧 pista molhada':'☀ pista seca'} · ${r.weather.track}° pista · ${r.incidents.length} ocorrência(s)</div></section><section class="panel official-results"><div class="panel-heading"><div><span class="eyebrow">CLASSIFICAÇÃO FINAL</span><h2>Todos os pilotos</h2></div><span class="badge">GRID · TEMPO · PONTOS</span></div><div class="result-list">${r.entries.map(e=>{const p=rider(e.riderId);return `<article class="result-row ${e.teamId==='player'?'player':''}"><b>P${e.position}</b><div class="result-avatar">${portrait(p)}</div><div><strong>${flag(p.nationality)} #${p.number} ${esc(p.name)}</strong><small>${esc(team(e.teamId).name)} · largou P${e.grid}</small></div><span>${time(e.time)}</span><span class="tyre-result">${e.status==='FINISHED'?e.points+' pts':T.status[e.status]||e.status}</span></article>`;}).join('')}</div></section><div class="columns section-label"><section class="panel"><h2>Consequências da etapa</h2><p>Sua equipe: <b>${r.entries.filter(e=>e.teamId==='player').reduce((a,e)=>a+e.points,0)} pontos</b>.</p><p>Caixa após pagamentos: <b>${money(cash(state))}</b>.</p>${btn('Examinar finanças','nav','data-view="finance"')}</section><section class="panel"><h2>Ocorrências</h2>${r.incidents.length?r.incidents.map(i=>`<p>#${rider(i.riderId).number} · ${esc(i.type)} · ${time(i.time)}</p>`).join(''):'<p>Sem incidentes registrados nesta corrida.</p>'}</section></div><div class="actions">${btn(state.round===9?'Encerrar temporada':'Avançar para próxima etapa','advance','','primary')}</div>`;}
function drawSession(){const q=state?.session;if(!q||view!=='session')return;const clock=document.getElementById('session-clock');if(!clock)return;const rows=ranking(q),leader=rows[0],lap=Math.min(q.laps,1+Math.floor(Math.max(...q.entries.map(e=>e.progress))));clock.textContent=q.kind==='race'?`VOLTA ${lap} / ${q.laps}`:time(Math.max(0,q.duration-q.elapsed));document.getElementById('weather').textContent=`${q.weather.air}° AR · ${q.weather.track}° PISTA · ${Math.round(q.weather.wet*100)}% MOLHADA`;document.getElementById('weather-trend').textContent=`Vento ${q.weather.wind} km/h · ${q.weather.forecast}`;document.getElementById('flag-state').textContent=q.state==='POST_SESSION'?'QUADRICULADA':q.state==='YELLOW_LOCAL'?'AMARELA LOCAL':q.state==='RED'?'VERMELHA':'PISTA ABERTA';document.getElementById('lap-progress').textContent=q.kind==='race'?`VOLTA ${lap} DE ${q.laps}`:'SESSÃO CRONOMETRADA';const latest=q.feed[0]?.text||'Sem comunicação recente.';document.getElementById('broadcast-headline').textContent=latest;document.getElementById('track-event').textContent=latest;const fastest=q.entries.filter(e=>e.best!=null).sort((a,b)=>a.best-b.best)[0];document.getElementById('fastest-lap').textContent=fastest?`#${fastest.number} ${time(fastest.best)}`:'Sem volta registrada';const playerRows=q.entries.filter(e=>e.teamId==='player');document.getElementById('strategy-pulse').textContent=playerRows.map(e=>`#${e.number} ${Math.round(100-e.wear)}%`).join(' · ')||'Aguardando';document.getElementById('timing').innerHTML=table(['P','Piloto','Gap / tempo','Pneu'],rows.map((e,i)=>({e,i})).filter(({e})=>filter==='all'||e.teamId==='player').map(({e,i})=>{const p=rider(e.riderId);return [i+1,`<span class="timing-rider ${e.teamId==='player'?'player-text':''}">${flag(p.nationality)} #${e.number} ${esc(p.short)}</span>`,q.kind==='race'?(e.status==='RETIRED'?'OUT':i===0?time(q.elapsed):'+'+Math.max(0,(leader.progress-e.progress)*currentCircuit(state).baseLap).toFixed(1)):time(e.best),`<span class="tyre-bullet" style="--tyre:${TYRES[e.tyre].color}">${TYRES[e.tyre].letter}</span>`];}));for(const e of playerRows){const status=document.getElementById('status-'+e.riderId);if(status)status.textContent=e.task>0?'PIT · '+Math.ceil(e.task)+'s':T.status[e.status];const telemetry=document.getElementById('telemetry-'+e.riderId);if(telemetry)telemetry.innerHTML=`<span>Pneu <b>${Math.round(100-e.wear)}%</b></span><span>Temp. <b>${Math.round(e.temperature)}°</b></span><span>Moto <b>${Math.round(e.health)}%</b></span><span>Combustível <b>${q.kind==='race'?e.fuel.toFixed(1)+'%':'—'}</b></span><span>Modo pneu <b>${({conserve:'ECO',balanced:'STD',push:'PUSH'}[e.tyreMode||'balanced'])}</b></span><span>Pit pronto <b>${TYRES[e.pitTyre||e.tyre].letter} · ${({safe:'SAFE',normal:'STD',fast:'FAST'}[e.pitMode||'normal'])}</b></span>`;}document.getElementById('radio-feed').innerHTML=q.feed.slice(0,8).map(f=>`<p><time>${time(f.time)}</time> ${esc(f.text)}</p>`).join('');document.getElementById('finish-btn').disabled=q.state!=='POST_SESSION';updateTrack(currentCircuit(state),q);}
function offer(kind,id){const value=quote(state,kind,id);modal(`<span class="eyebrow">MESA DE NEGOCIAÇÃO</span><h2>${esc(entityName(kind,id))}</h2><p>Contrato por etapa. ${kind==='sponsor'?'Você recebe após cada corrida.':'Luvas de 8% de uma parcela na assinatura.'}</p><form id="offer-form" data-kind="${kind}" data-id="${id}">${label('Valor por etapa (€)',`<input type="number" name="value" min="1" max="10000000" step="1" required value="${value}">`)}${label('Duração',`<select name="duration">${[1,2,3].map(n=>option(n,n+' temporada(s)')).join('')}</select>`)}<p id="counter" class="hint">Referência: ${money(value)}. Você pode fazer uma contraproposta.</p><button class="primary wide">Enviar proposta</button></form>`);}
document.addEventListener('submit',event=>{event.preventDefault();const f=event.target;try{if(f.id==='new-career'){const options=Object.fromEntries(new FormData(f));state=createCareer(options);view='dashboard';persist();render();modal(tutorialContent());}else if(f.id==='offer-form'){const r=negotiate(state,{kind:f.dataset.kind,id:f.dataset.id,value:+f.elements.value.value,duration:+f.elements.duration.value});persist();if(r.accepted){dialog.close();toast('Contrato assinado. Compromisso registrado.');render();}else document.getElementById('counter').textContent='Contraproposta recebida: '+money(r.counter)+'. Ajuste o valor para continuar.';}else if(f.id==='setup-form'){setSetup(state,[0,1,2].map(i=>+f.elements['s'+i].value));persist();toast('Acerto aplicado.');render();}else if(f.id==='settings-form'){for(const k of ['guide','contrast','reducedMotion','sound'])state.settings[k]=f.elements[k].checked;state.settings.scale=+f.elements.scale.value;state.settings.graphics=f.elements.graphics.value;persist();toast('Preferências atualizadas.');render();}}catch(e){toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.type==='range')e.target.nextElementSibling.value=e.target.value;});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.pace)command(state,el.dataset.pace,'pace',+el.value);if(el.dataset.engine)command(state,el.dataset.engine,'engineMode',el.value);if(el.dataset.electronics)command(state,el.dataset.electronics,'electronics',el.value);if(el.dataset.brake)command(state,el.dataset.brake,'brakeBias',+el.value);if(el.dataset.tyreMode)command(state,el.dataset.tyreMode,'tyreMode',el.value);if(el.dataset.pitPlan)command(state,el.dataset.pitPlan,'pitPlan',el.value);if(el.dataset.pitMode)command(state,el.dataset.pitMode,'pitMode',el.value);if(el.dataset.engine||el.dataset.electronics||el.dataset.brake||el.dataset.tyreMode||el.dataset.pitPlan||el.dataset.pitMode)persist();if(el.dataset.tyre){command(state,el.dataset.tyre,'tyre',el.value);persist();}if(el.id==='timing-filter'){filter=el.value;drawSession();}if(el.id==='import-file'&&el.files[0]){if(el.files[0].size>12000000)throw Error('Arquivo muito grande.');const imported=decode(await el.files[0].text());if(state)save(state,'3');state=imported;view='dashboard';paused=true;persist();render();toast('Backup importado. A carreira anterior foi preservada no slot 3.');}}catch(error){toast(error.message);render();}});
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();const a=el.dataset.action,id=el.dataset.id;try{switch(a){case'nav':view=el.dataset.view;render();break;case'tutorial':modal(tutorialContent());break;case'tutorial-go':{const completed=state.part4.tutorial.completed;if(!completed.includes(el.dataset.step))completed.push(el.dataset.step);view=el.dataset.view;dialog.close();persist();render();break;}case'tutorial-complete':state.part4.tutorial.completed=['fundacao','contratos','fim-de-semana','pitwall','resultado','inbox'];state.part4.tutorial.dismissed=true;dialog.close();persist();toast('Tutorial concluído. O guia continua disponível no topo.');break;case'mail-read':{const id=+el.dataset.id;if(!state.part4.mailbox.read.includes(id))state.part4.mailbox.read.push(id);persist();render();break;}case'close':dialog.close();break;case'people-tab':selectedKind=el.dataset.kind;render();break;case'offer':offer(el.dataset.kind,id);break;case'profile':{const p=(el.dataset.kind==='rider'?state.riders:state.staff).find(p=>p.id===id);modal(`<div class="profile-head">${portrait(p)}<div><h2>${esc(p.name)}</h2><p>${esc(p.biography||p.personality)}</p><p>${p.agent?esc(p.agent):ROLE_NAMES[p.role]}</p></div></div>${bars(p.attributes)}`);break;}case'circuit':{const c=CIRCUITS.find(c=>c.id===id);modal(`<h2>${flag(c.country)} ${c.name}</h2>${trackSVG(c)}<p>${c.length} km · ${c.temp} °C · Chuva ${Math.round(c.rain*100)}%</p><p>Traçado original fictício. O mapa representa os mesmos segmentos usados pela simulação.</p>`);break;}case'continue':if(state.phase==='management'){const missing=readiness(state);if(missing.length)view=missing[0].includes('patrocínio')||missing[0].includes('fabricante')?'partners':'people';else{enterWeekend(state);view='session';persist();}}else view=state.phase==='grid'?'grid':['result','seasonEnd'].includes(state.phase)?'result':'session';render();break;case'start-session':state.weekend.tyre=document.getElementById('pre-tyre').value;startSession(state,state.phase);paused=true;view='session';persist();render();toast('Sessão aberta e pausada. Libere as motos e retome o relógio.');break;case'race-start':state.weekend.tyre=document.getElementById('grid-tyre').value;state.weekend.pace=+document.getElementById('grid-pace').value;state.weekend.engineMode=document.getElementById('grid-engine').value;state.weekend.electronics=document.getElementById('grid-electronics').value;state.weekend.brakeBias=+document.getElementById('grid-brake').value;state.phase='race';startSession(state,'race');paused=false;view='session';persist();render();break;case'pause':paused=!paused;document.getElementById('pause-btn').textContent=paused?'▶ Retomar':'Ⅱ Pausar';break;case'speed':speed=+el.dataset.speed;render();break;case'out':case'box':command(state,id,a);drawSession();persist();break;case'pit-plan-label':toast('Escolha o composto e o modo de pit neste cartão antes de chamar a moto.');break;case'finish-session':if(state.session.kind==='race'){settleRace(state);view='result';}else{finishTimedSession(state);view=state.phase==='grid'?'grid':'session';}paused=true;persist();render();break;case'recommend':setSetup(state,[...state.weekend.feedback]);persist();render();toast('Recomendação aplicada.');break;case'advance':advance(state);view=state.phase==='seasonEnd'?'result':'dashboard';persist();render();break;case'next-season':nextSeason(state);view='dashboard';persist();render();break;case'develop':confirmAction('Aprovar desenvolvimento?',`O custo base é ${money(B.upgradeCost)} ajustado pela categoria e filosofia. Duração: duas etapas. Risco: 12%.`,'develop-confirm',`data-id="${id}"`);break;case'develop-confirm':develop(state,id);dialog.close();persist();render();toast('Projeto iniciado.');break;case'credit-request':confirmAction(state.debt?'Quitar o crédito?':'Contratar crédito operacional?',state.debt?`Pagamento integral de ${money(state.debt)}.`:`Entrada de ${money(B.creditLimit)}; juros de 2,5% por etapa até a quitação.`,'credit');break;case'credit':state.debt?repay(state):credit(state);dialog.close();persist();render();break;case'terminate-request':confirmAction('Rescindir contrato?','A multa será de 25% das parcelas restantes. O parceiro será liberado imediatamente.','terminate',`data-id="${id}"`);break;case'terminate':terminate(state,id);dialog.close();persist();render();break;case'save':persist();toast('Carreira salva.');break;case'manual-save-request':confirmAction('Salvar no slot '+el.dataset.slot+'?','O conteúdo anterior terá uma cópia de segurança local.','manual-save',`data-slot="${el.dataset.slot}"`);break;case'manual-save':save(state,el.dataset.slot);dialog.close();render();toast('Slot salvo.');break;case'load-request':confirmAction('Carregar esta carreira?','O progresso atual será salvo automaticamente antes da troca.','load',`data-slot="${el.dataset.slot}"`);break;case'load':{const loaded=load(el.dataset.slot);if(state&&el.dataset.slot!=='auto')persist();state=loaded.state;view='dashboard';paused=true;dialog.close();render();if(loaded.recovered)toast('Carreira recuperada da cópia de segurança.');else if(loaded.migrated)toast('Carreira anterior migrada para a Parte 3. O slot antigo foi preservado.');break;}case'export':{const blob=new Blob([encode(state)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='mrm-temporada-'+state.season+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}case'import':document.getElementById('import-file').click();break;case'hide-guide':state.settings.guide=false;persist();render();break;case'help':modal(`<div class="profile-head">${image('guide','guide-avatar','Sofia')}<div><h2>Sofia · Central de ajuda</h2><p>${state?T.guide[state.phase]:'Crie sua equipe para começar.'}</p></div></div><h3>Como jogar</h3><p>1. Contrate dois pilotos, engenharia e mecânica.<br>2. Feche fabricante e patrocínio.<br>3. Viaje, treine e ajuste a moto.<br>4. Classifique, escolha pneus e dispute a corrida.<br>5. Confira o resultado e avance.</p><h3>Na pista</h3><p>Espaço pausa o relógio. Os botões 1× a 32× aceleram a mesma simulação. Box troca pneus ao completar a volta. Mapa de motor, eletrônica e freio alteram ritmo, consumo, desgaste e risco em tempo real. Em treino, as motos retornam após três voltas cronometradas.</p><p>“Projeção” não inclui prêmios futuros. Contratos duram temporadas, mas as parcelas são por etapa.</p>${btn('Reativar orientações','show-guide','','primary')}`);break;case'show-guide':state.settings.guide=true;dialog.close();persist();render();break;case'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Tela cheia não está disponível neste navegador.');break;case'menu-request':confirmAction('Voltar ao menu?','A carreira atual será salva automaticamente.','menu');break;case'menu':persist();state=null;paused=true;dialog.close();render();break;}}catch(e){toast(e.message);}});
document.addEventListener('keydown',e=>{if(e.code==='Space'&&state?.session&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();paused=!paused;const b=document.getElementById('pause-btn');if(b)b.textContent=paused?'▶ Retomar':'Ⅱ Pausar';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){paused=true;if(state)persist();}});
window.addEventListener('pagehide',()=>{if(state)persist();});
function frame(now){const dt=Math.min((now-lastFrame)/1000,.2);lastFrame=now;const blocked=false;if(state?.session&&!paused&&!document.hidden&&!blocked&&!dialog.open){accumulator+=dt*speed;while(accumulator>=B.tick){tick(state);accumulator-=B.tick;if(state.session.state==='POST_SESSION'){paused=true;persist();break;}}}if(now-lastDraw>250){drawSession();lastDraw=now;}if(state?.session&&now-lastSave>10000)persist();requestAnimationFrame(frame);}
try{const response=await fetch('asset-manifest.json');if(!response.ok)throw Error('Catálogo de imagens indisponível.');manifest=await response.json();render();requestAnimationFrame(frame);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){app.innerHTML=`<div class="loading"><h1>Não foi possível abrir o paddock.</h1><p>${esc(e.message)}</p><p>Abra por um servidor HTTP ou GitHub Pages. Consulte o LEIA-ME.</p><button onclick="location.reload()">Tentar novamente</button></div>`;}






